package com.codearena.controller;
import com.codearena.entity.*;import com.codearena.repository.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
import java.util.*;
@RestController public class ProfileController {
 @Autowired SubmissionRepository submissions; @Autowired ProblemRepository problems;
 @GetMapping("/api/profile") public ResponseEntity<?> profile(@RequestParam(required=false)String userId){if(userId==null)return ResponseEntity.badRequest().body(Map.of("error","userId required"));List<Submission> all=submissions.findByUserIdOrderByCreatedAtDesc(userId);Set<String> solved=new HashSet<>();Map<String,Integer>by=new LinkedHashMap<>();by.put("Easy",0);by.put("Medium",0);by.put("Hard",0);Map<String,Set<String>>unique=new HashMap<>();unique.put("Easy",new HashSet<>());unique.put("Medium",new HashSet<>());unique.put("Hard",new HashSet<>());Map<String,Integer>activity=new TreeMap<>();int accepted=0;for(Submission s:all){String date=s.getCreatedAt().toLocalDate().toString();activity.put(date,activity.getOrDefault(date,0)+1);if("Accepted".equals(s.getStatus())){accepted++;solved.add(s.getProblemId());Optional<Problem>p=problems.findById(s.getProblemId());if(p.isPresent()){String d=p.get().getDifficulty();if(unique.containsKey(d))unique.get(d).add(s.getProblemId());}}}by.put("Easy",unique.get("Easy").size());by.put("Medium",unique.get("Medium").size());by.put("Hard",unique.get("Hard").size());List<Map<String,Object>>recent=new ArrayList<>();for(Submission s:all.stream().limit(10).toList()){Optional<Problem>p=problems.findById(s.getProblemId());Map<String,Object>m=new LinkedHashMap<>();m.put("id",s.getId());m.put("problemId",s.getProblemId());m.put("problemTitle",p.map(Problem::getTitle).orElse("Problem "+s.getProblemId()));m.put("difficulty",p.map(Problem::getDifficulty).orElse("Medium"));m.put("language",s.getLanguage());m.put("status",s.getStatus());m.put("runtime",s.getRuntime());m.put("memory",s.getMemory());m.put("createdAt",s.getCreatedAt());recent.add(m);}Map<String,Object>out=new LinkedHashMap<>();out.put("totalSolved",solved.size());out.put("totalSubmissions",all.size());out.put("acceptedSubmissions",accepted);out.put("solvedByDifficulty",by);out.put("acceptanceRate",all.isEmpty()?0:Math.round(accepted*100.0/all.size()));out.put("activity",activity);out.put("recentSubmissions",recent);return ResponseEntity.ok(out);}
}
